scwin.__clickFilter = function(p) {
    var el = scwin.__getDom($p.id + "gridView1_customFilter_list").getElementsByClassName('w2list_listRow');
    return el[p].childNodes[0].click();
}
scwin.__checkExceptFilter = function(val) {
    var count = 0;
    ((j) => j.length ? j : $('#mf_gridView1_body_tbody tr'))($('#gridView1_body_tbody tr')).find("td").not("#_headerRowStatus").each(function() {
        if (scwin.__getJq(this).text() == val) {
            count++;
        }
    });
    return count == 0;
}
scwin.__isShowFilter = function(val) {
    var div = ((j) => j.length ? j : $('#mf_gridView1_customFilter_list'))($('#gridView1_customFilter_list')).find(".w2list_listRow");
    return div.length == val;
}
scwin.__isShowInitData = function() {
    return ((j) => j.length ? j : $('#mf_gridView1_body_tbody tr'))($('#gridView1_body_tbody tr')).length == dataList1.getRowCount();
}

